import React, { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import Button from "../components/common/Button";
import { useUI } from "../context/UIContext";
import styles from "../Result.module.css";
import { saveToSheet } from "../components/utils/googleSheetLogger";

const Result = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { setHeroData, allAnswers } = useUI();
  const { finalData } = location.state || {};

  // 🚀 關鍵 1：確保每次進入組件，初始值絕對是 false
  const [isSurveyClicked, setIsSurveyClicked] = useState(false);

  const SURVEY_URL =
    "https://docs.google.com/forms/d/e/1FAIpQLScHyyUgqi5TM3Rmz53ZmtBzv_w4l424x1WwAntH_d7TGH-Crg/viewform?usp=send_form";

  const flowCharts = {
    BCT: "https://sdm-5cbs.onrender.com/assets/images/bct.png",
    SM: "https://sdm-5cbs.onrender.com/assets/images/sm.png",
  };

  // 🚀 關鍵 2：組件掛載時明確執行鎖定
  useEffect(() => {
    setIsSurveyClicked(false); // 強制初始化

    setHeroData({
      imageUrl:
        "https://web-production-fbb7b.up.railway.app/static/helperinside.png",
      title: "評估結果建議",
      description: `${allAnswers.userName}您好，基於您的選擇與心情反應，以下是醫療團隊提供的決策參考。`,
    });

    if (allAnswers?.userName && finalData) {
      submitDataToSheet();
    }
  }, [setHeroData]); // 移除依賴 finalData 的頻繁觸發，只需進場執行一次

  const submitDataToSheet = async () => {
    try {
      const logData = {
        date: new Date().toLocaleDateString(),
        userName: allAnswers.userName,
        birthDate: allAnswers.birthday || allAnswers.birthDate,
        selectedTopic: allAnswers.selectedTopic,
        details: JSON.stringify(allAnswers.answers),
        finalResult: finalData.title,
      };
      await saveToSheet(logData);
    } catch (error) {
      console.error("同步失敗", error);
    }
  };

  if (!finalData) {
    return (
      <div className={styles.emptyState}>
        <h3>尚未完成評估</h3>
        <p>請回問卷頁面重新操作。</p>
        <Button onClick={() => navigate("/selection")}>返回主選單</Button>
      </div>
    );
  }

  // --- 決定顯示哪張圖 ---
  let displayType = finalData.type;
  if (!displayType && finalData.title) {
    if (finalData.title.includes("部分")) displayType = "BCT";
    else if (finalData.title.includes("全乳房")) displayType = "SM";
  }
  const chartUrl = flowCharts[displayType];

  return (
    <div className={styles.container}>
      {/* 內容區塊 */}
      <div className={styles.resultCard}>
        <h2 className={styles.resultTitle}>{finalData.title}</h2>
        <hr className={styles.divider} />
        <div
          className={styles.description}
          dangerouslySetInnerHTML={{ __html: finalData.description }}
        />
      </div>

      {/* 流程圖 */}
      {chartUrl && (
        <div className={styles.flowChartSection}>
          <h3 className={styles.sectionTitle}>您的預計治療流程</h3>
          <div className={styles.imageWrapper}>
            <img
              src={chartUrl}
              alt="治療流程圖"
              className={styles.flowImage}
              onClick={() => window.open(chartUrl, "_blank")}
            />
          </div>
        </div>
      )}

      {/* 小提醒 */}
      <div className={styles.tipBox}>
        💡 <strong>小提醒：</strong>{" "}
        這個結果代表了您目前的價值偏好，建議您將此頁面截圖或列印。
      </div>

      {/* 問卷區塊 */}
      <div
        key={location.key}
        className={styles.surveySection}
        style={{
          margin: "20px 0",
          padding: "20px",
          backgroundColor: isSurveyClicked ? "#f6ffed" : "#fff7e6",
          border: `1px solid ${isSurveyClicked ? "#b7eb8f" : "#ffd591"}`,
          borderRadius: "12px",
          textAlign: "center",
          minHeight: "100px",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          width: "100%",
          maxWidth: "480px",
          boxSizing: "border-box",
        }}
      >
        <p
          style={{
            fontWeight: "bold",
            marginBottom: isSurveyClicked ? "0" : "10px",
            color: isSurveyClicked ? "#52c41a" : "#d46b08",
            fontSize: "1.1rem",
          }}
        >
          {isSurveyClicked ? "感謝您的填寫" : "最後一步：請填寫問卷"}
        </p>
        {!isSurveyClicked ? (
          <a
            href={SURVEY_URL}
            target="_blank"
            rel="noopener noreferrer"
            onClick={() => setIsSurveyClicked(true)}
            style={{
              display: "inline-block",
              padding: "10px 24px",
              backgroundColor: "#fa8c16",
              color: "#fff",
              borderRadius: "6px",
              textDecoration: "none",
              fontWeight: "bold",
            }}
          >
            點此填寫問卷
          </a>
        ) : null}
      </div>

      {/* 功能按鈕 */}
      <div className={styles.buttonGroup}>
        <Button
          variant="outline"
          style={{ flex: 1 }}
          onClick={() => window.print()}
        >
          列印/儲存 PDF
        </Button>
        <Button
          style={{ flex: 1 }}
          onClick={() => navigate("/selection")}
          isDisabled={!isSurveyClicked}
        >
          完成並回首頁
        </Button>
      </div>
    </div>
  );
};

export default Result;
